const data = $json;
const formatRp = (num) => 'Rp ' + Number(num || 0).toLocaleString('id-ID');

const todayExpense = Number(data.today_expense || 0);
const todayIncome = Number(data.today_income || 0);
const todayNet = todayIncome - todayExpense;

const monthExpense = Number(data.month_expense || 0);
const monthIncome = Number(data.month_income || 0);
const monthNet = monthIncome - monthExpense;

const now = new Date();
const dateStr = now.toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Asia/Jakarta' });
const monthName = now.toLocaleDateString('id-ID', { month: 'long', year: 'numeric', timeZone: 'Asia/Jakarta' });

let msg = `📊 *REKAPITULASI KEUANGAN PRIBADI*\n`;
msg += `📅 _${dateStr}_\n\n`;

msg += `🗓️ *Hari Ini:*\n`;
msg += `  🔺 Pengeluaran : *${formatRp(todayExpense)}*\n`;
msg += `  🟢 Pemasukan   : *${formatRp(todayIncome)}*\n`;
msg += `  ⚖️ Selisih     : *${formatRp(todayNet)}*\n\n`;

msg += `📆 *Bulan Ini (${monthName}):*\n`;
msg += `  🔺 Pengeluaran : *${formatRp(monthExpense)}*\n`;
msg += `  🟢 Pemasukan   : *${formatRp(monthIncome)}*\n`;
msg += `  💰 Arus Kas    : *${formatRp(monthNet)}*\n`;
msg += `  📝 Total Catatan : *${data.total_transactions_month || 0} transaksi*\n\n`;

if (monthExpense > monthIncome && monthIncome > 0) {
  msg += `⚠️ *Perhatian:* Pengeluaran bulan ini lebih besar daripada pemasukan!`;
} else if (todayExpense === 0 && todayIncome === 0) {
  msg += `💡 Belum ada transaksi tercatat untuk hari ini. Tetap semangat!`;
} else {
  msg += `✨ *Catatan:* Kondisi keuangan Anda terpantau aman dan rapi!`;
}

const triggerJson = $('Telegram Trigger').first().json;
const chatId = triggerJson.message?.chat?.id;

return [{
  json: {
    chat_id: chatId,
    rekap_text: msg
  },
  pairedItem: { item: 0 }
}];

