parameters.jsCode:
const triggerItem = $('Telegram Trigger').first().json;
const rawMessage = (triggerItem.message?.text || '').trim();
const telegramUserId = triggerItem.message?.from?.id;
const chatId = triggerItem.message?.chat?.id;

let aiRaw = '';
try {
  aiRaw = $json.candidates[0].content.parts[0].text;
} catch (e) {
  aiRaw = '{}';
}

let parsed = {};
try {
  const cleaned = aiRaw.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {};
}

let amount = Number(parsed.amount) || 0;
let type = (parsed.type || '').toLowerCase().trim();
let category = (parsed.category || '').trim();
let description = (parsed.description || '').trim();

// FALLBACK / RESILIENCE MECHANISM:
// Jika Google Gemini API rate-limited (HTTP 429), error, response kosong,
// atau gagal menghasilkan nominal (> 0), gunakan fallback parser regex lokal bahasa Indonesia.
if (!amount || amount <= 0 || isNaN(amount)) {
  const text = rawMessage.toLowerCase().trim();

  // 1. Deteksi Nominal & Pengali (...rb, ...ribu, ...k, ...jt, ...juta, atau angka langsung)
  const suffixRegex = /(?:rp\.?\s*)?(\d+(?:[.,]\d+)?)\s*(jt|juta|rb|ribu|k)\b/i;
  const suffixMatch = text.match(suffixRegex);

  if (suffixMatch) {
    const numStr = suffixMatch[1].replace(',', '.');
    let mult = 1;
    const unit = suffixMatch[2].toLowerCase();
    if (unit === 'jt' || unit === 'juta') mult = 1000000;
    else if (unit === 'rb' || unit === 'ribu' || unit === 'k') mult = 1000;
    amount = Math.round(parseFloat(numStr) * mult);
  } else {
    // Angka ribuan dengan pemisah titik/koma (e.g. 25.000, 1.500.000, 7,000)
    const thousandRegex = /(?:rp\.?\s*)?(\d{1,3}(?:[.,]\d{3})+(?:,\d+)?)\b/i;
    const thousandMatch = text.match(thousandRegex);
    if (thousandMatch) {
      const numStr = thousandMatch[1].replace(/\./g, '').replace(/,/g, '');
      amount = parseInt(numStr, 10);
    } else {
      // Nominal angka langsung (e.g. 7000, 25000)
      const plainRegex = /(?:rp\.?\s*)?(\b\d{3,12}\b)/i;
      const plainMatch = text.match(plainRegex);
      if (plainMatch) {
        amount = parseInt(plainMatch[1], 10);
      }
    }
  }

  // 2. Deteksi Kategori & Tipe Otomatis
  const incomeKeywords = ['gaji', 'bonus', 'cashback', 'terima', 'dapat', 'pemasukan', 'upah', 'honor', 'thr', 'dividen', 'penjualan', 'hasil', 'pendapatan', 'transferan'];
  const foodKeywords = ['makan', 'minum', 'kopi', 'cafe', 'kafe', 'resto', 'restoran', 'sarapan', 'lunch', 'dinner', 'warteg', 'padang', 'bakso', 'mie', 'nasi', 'snack', 'jajan', 'cemilan', 'teh', 'boba', 'ayam', 'roti', 'es'];
  const billKeywords = ['kos', 'kost', 'listrik', 'token', 'pln', 'wifi', 'indihome', 'pdam', 'air', 'pulsa', 'kuota', 'sewa', 'iuran', 'kontrakan', 'bpjs', 'cicilan', 'pajak', 'tagihan', 'langganan', 'netflix', 'spotify'];
  const transportKeywords = ['bensin', 'pertalite', 'pertamax', 'solar', 'grab', 'gojek', 'ojol', 'maxim', 'gocar', 'goride', 'parkir', 'tol', 'tiket', 'kereta', 'krl', 'mrt', 'bus', 'transjakarta', 'angkot', 'taksi', 'travel'];
  const healthKeywords = ['obat', 'apotek', 'apotik', 'dokter', 'klinik', 'rs', 'rumah sakit', 'vitamin', 'medis', 'periksa', 'paracetamol', 'bidan', 'terapi'];

  if (incomeKeywords.some(kw => text.includes(kw))) {
    category = 'Pendapatan';
    type = 'income';
  } else if (foodKeywords.some(kw => text.includes(kw))) {
    category = 'Makanan';
    type = 'expense';
  } else if (billKeywords.some(kw => text.includes(kw))) {
    category = 'Tagihan';
    type = 'expense';
  } else if (transportKeywords.some(kw => text.includes(kw))) {
    category = 'Transportasi';
    type = 'expense';
  } else if (healthKeywords.some(kw => text.includes(kw))) {
    category = 'Kesehatan';
    type = 'expense';
  } else {
    category = 'Belanja';
    type = 'expense';
  }

  // Bersihkan keterangan dari nominal angka jika memungkinkan
  let cleanedDesc = rawMessage
    .replace(/(?:rp\.?\s*)?(\d+(?:[.,]\d+)?)\s*(jt|juta|rb|ribu|k)\b/gi, '')
    .replace(/(?:rp\.?\s*)?(\d{1,3}(?:[.,]\d{3})+(?:,\d+)?)\b/gi, '')
    .replace(/(?:rp\.?\s*)?(\b\d{3,12}\b)/gi, '')
    .trim();
  description = cleanedDesc || rawMessage.trim();
}

// Validasi tipe (wajib expense atau income)
if (type !== 'expense' && type !== 'income') {
  type = 'expense';
}

// Validasi kategori (wajib salah satu dari 6 kategori valid)
const validCategories = ['Makanan', 'Belanja', 'Transportasi', 'Kesehatan', 'Tagihan', 'Pendapatan'];
if (!validCategories.includes(category)) {
  category = type === 'income' ? 'Pendapatan' : 'Belanja';
}

const isValid = amount > 0 && !isNaN(amount);

if (!description || description.toLowerCase() === 'non-transaksi' || description.toLowerCase() === 'bukan transaksi') {
  description = rawMessage.trim();
}
if (description.length > 255) {
  description = description.substring(0, 255);
}

const escapedDescription = description.replace(/'/g, "''").replace(/\\/g, '\\\\');
const escapedRawMessage = rawMessage.replace(/'/g, "''").replace(/\\/g, '\\\\');

return [{
  json: {
    telegram_user_id: telegramUserId,
    chat_id: chatId,
    raw_message: rawMessage,
    escaped_raw_message: escapedRawMessage,
    type: type,
    category: category,
    amount: amount,
    description: description,
    escaped_description: escapedDescription,
    is_valid: isValid
  },
  pairedItem: { item: 0 }
}];

parameters.query:
=SELECT 
  COALESCE(SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END), 0) AS today_total_expense,
  COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END), 0) AS today_total_income
FROM transactions
WHERE telegram_user_id = {{ $('Code: Parse & Validate AI Output').first().json.telegram_user_id }}
  AND transaction_date >= CURRENT_DATE;

