const parsedItem = $('Code: Parse & Validate AI Output').first().json;
const summary = $json;

const formatRp = (num) => 'Rp ' + Number(num || 0).toLocaleString('id-ID');
const isExpense = parsedItem.type === 'expense';
const icon = isExpense ? '💸' : '💰';
const typeLabel = isExpense ? 'Pengeluaran' : 'Pemasukan';

let categoryIcon = '📦';
switch (parsedItem.category) {
  case 'Makanan': categoryIcon = '🍔'; break;
  case 'Belanja': categoryIcon = '🛍️'; break;
  case 'Transportasi': categoryIcon = '🛵'; break;
  case 'Kesehatan': categoryIcon = '💊'; break;
  case 'Tagihan': categoryIcon = '🧾'; break;
  case 'Pendapatan': categoryIcon = '💵'; break;
}

const todayExpense = Number(summary.today_total_expense || 0);
const todayIncome = Number(summary.today_total_income || 0);

const safeDesc = (parsedItem.description || '').replace(/([_*[`])/g, '\\$1');

let msg = `✅ *Transaksi Berhasil Dicatat!*\n\n`;
msg += `${icon} *Tipe:* ${typeLabel}\n`;
msg += `${categoryIcon} *Kategori:* ${parsedItem.category}\n`;
msg += `💵 *Nominal:* *${formatRp(parsedItem.amount)}*\n`;
msg += `📝 *Keterangan:* ${safeDesc}\n\n`;
msg += `────────────────────\n`;
msg += `📊 *Total Hari Ini:*\n`;
msg += `🔺 Pengeluaran : *${formatRp(todayExpense)}*\n`;
msg += `🟢 Pemasukan   : *${formatRp(todayIncome)}*\n\n`;
msg += `💡 _Ketik /rekap untuk melihat rekapitulasi lengkap bulan ini._`;

return [{
  json: {
    chat_id: parsedItem.chat_id,
    text: msg
  },
  pairedItem: { item: 0 }
}];
